def choose_move(observation):
    x, y = observation['self_position']
    def sign(n): return (n > 0) - (n < 0)
    move_options = [(-1,0),(1,0),(0,-1),(0,1)]
    def dist(p): return abs(p[0]-x)+abs(p[1]-y)
    resources = observation['resources']
    if resources:
        best = min(resources, key=lambda r: dist(r))
        dx = sign(best[0]-x)
        dy = sign(best[1]-y)
        if (dx,dy) in move_options:
            return [dx,dy]
    opponents = observation['opponent_position']
    if opponents:
        dx = sign(opponents[0][0]-x)
        dy = sign(opponents[0][1]-y)
        if (dx,dy) in move_options:
            return [dx,dy]
    return [0,0]
